	const handleCheckInSubmit = async (e) => {
		e.preventDefault();
		const todayStr = getLocalYYYYMMDD();
		const found = bookings.find((b) => {
			const dt = getSafeDateTime(b);
			return (b.customerPhone === checkInInput || b.id === checkInInput) && dt?.startsWith(todayStr) && ["รอการยืนยัน", "ยืนยันแล้ว"].includes(getBookingStatus(b));
		});
		if (found) {
			await updateBookingStatus(found.id, "กำลังใช้บริการ");
			setCheckInInput("");
			setIsCheckInOpen(false);
			showToast(`เช็คอินสำเร็จ! อัปเดตคิวของ ${found.customerName} เป็น "กำลังใช้บริการ"`);
		} else showToast("ไม่พบคิวนัดหมายของวันนี้ที่ตรงกับเบอร์โทร/รหัสอ้างอิง หรือเช็คอินไปแล้ว");
	};
